"use client";

import * as motion from "motion/react-client";
import { Clock, ArrowRight } from "lucide-react";
import { useEffect } from "react";
import SectionHeading from "../../../ui/portfolio/section-heading";
import { getCalApi } from "@calcom/embed-react";

interface CalBookerProps {
  duration?: string;
}

const bookingOptions = [
  {
    duration: "15min",
    durationDisplay: "15 Min Discovery Call",
    title: "Free Expert Consultation & Intro",
    description:
      "Book a brief discovery call to evaluate your project needs, discuss technical goals, and see how professional software engineering can scale your business.",
  },
  {
    duration: "30min",
    durationDisplay: "30 Min Strategy Session",
    title: "1-on-1 Technical Strategy & Planning",
    description:
      "Schedule an in-depth session for expert technical guidance, architectural planning, and deep-dive problem solving tailored to your specific software requirements.",
  },
];

export default function BookingCards({ duration = "30min" }: Readonly<CalBookerProps>) {
  useEffect(() => {
    // Initialize Cal API for each booking option
    Promise.all(
      bookingOptions.map(async (option) => {
        const cal = await getCalApi({ namespace: option.duration });
        cal("ui", {
          hideEventTypeDetails: false,
          layout: "month_view",
        });
      })
    ).catch(console.error);
  }, []);

  return (
    <>
      <SectionHeading className="text-3xl font-bold text-white mt-10">
        Schedule Your Project Call{" "}
      </SectionHeading>
      <p className="text-zinc-400 text-base max-w-2xl ">
        Book a time that works best for you to discuss your web development
        goals. All sessions are held online and provide a risk-free opportunity
        to explore technical solutions for your business.
      </p>

      <div className="grid grid-cols-1 md:grid-cols-2 mt-4 gap-6">
        {bookingOptions.map((option, idx) => (
          <motion.div
            key={option.duration}
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: idx * 0.2 }}
            viewport={{ once: true }}
            className={`relative group p-8 transition-all duration-300 overflow-hidden border border-zinc-800  cursor-pointer  hover:border-primary`}
          >
            {/* Content */}
            <div className="relative z-10 space-y-6">
              {/* Duration badge */}
              <div className="flex items-center gap-2 w-fit">
                <Clock className="w-4 h-4 text-blue-400" />
                <span className="text-sm font-mono text-blue-400 uppercase tracking-widest">
                  {option.durationDisplay}
                </span>
              </div>

              {/* Title and description */}
              <div className="space-y-3">
                <h4 className="text-2xl font-bold text-white">
                  {option.title}
                </h4>
                <p className="text-zinc-400 text-sm leading-relaxed">
                  {option.description}
                </p>
              </div>

              {/* Price and CTA */}
              <div className="flex items-center justify-between pt-4 border-t border-white/10">
                <button
                  data-cal-namespace={option.duration}
                  data-cal-link={`razeev/${option.duration}`}
                  data-cal-config='{"layout":"month_view","useSlotsViewOnSmallScreen":"true"}'
                  className="inline-flex items-center gap-2 px-6 py-3    transition-all duration-300 group/btn cursor-pointer bg-white text-black font-black text-xs uppercase tracking-[0.2em]  transform hover:-translate-y-1 active:scale-95 border-2 border-white "
                >
                  Book Now
                  <ArrowRight className="w-5 h-5 group-hover/btn:translate-x-1 transition-transform" />
                </button>
              </div>
            </div>
          </motion.div>
        ))}
      </div>
    </>
  );
}

@theme inline {
  --color-primary-light: var(--primary);
  --color-primary-hover: var(--primary);
  --color-accent-cyan: var(--secondary);
  --color-accent-purple: var(--primary);
  --color-info: var(--primary);
  --shadow-glow: 0 0 20px color-mix(in oklab, var(--primary) 15%, transparent);
  --shadow-glow-lg: 0 0 30px color-mix(in oklab, var(--primary) 25%, transparent);
  --font-heading: var(--font-sans);
}

@layer components {
  /* Example utility combining the new theme variables */
  .btn-primary-glow {
    @apply bg-primary text-primary-foreground shadow-glow hover:shadow-glow-lg
           transition-all duration-200 active:scale-95;
  }

  .blog-content > table,
  .blog-content > .table-wrapper > table {
    width: 100%;
    margin: 2rem 0;
    border-collapse: separate;
    border-spacing: 0;
    overflow: hidden;
    border: 1px solid var(--border);
    background: color-mix(in oklab, var(--background) 60%, transparent);
    box-shadow: 0 1px 2px rgb(0 0 0 / 0.08);
    font-size: 0.95rem;
  }

  .blog-content > table[header-row="true"] tbody tr:first-child td,
  .blog-content > table thead th,
  .blog-content > .table-wrapper > table[header-row="true"] tbody tr:first-child td,
  .blog-content > .table-wrapper > table thead th {
    background: color-mix(in oklab, var(--muted) 40%, transparent);
    color: var(--foreground);
    font-size: 0.625rem;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
  }

  .blog-content > table td,
  .blog-content > table th,
  .blog-content > .table-wrapper > table td,
  .blog-content > .table-wrapper > table th {
    padding: 0.9rem 1rem;
    border-bottom: 1px solid var(--border);
    text-align: left;
    vertical-align: top;
    color: var(--muted-foreground);
  }

  .blog-content > table tr:last-child td,
  .blog-content > table tr:last-child th,
  .blog-content > .table-wrapper > table tr:last-child td,
  .blog-content > .table-wrapper > table tr:last-child th {
    border-bottom: 0;
  }

  .blog-content > table td code,
  .blog-content > table th code,
  .blog-content > .table-wrapper > table td code,
  .blog-content > .table-wrapper > table th code {
    display: inline-block;
    padding: 0.1rem 0.35rem;
    border-radius: calc(var(--radius) * 0.45);
    background: var(--muted);
    color: var(--foreground);
    font-family: var(--font-sans);
    font-size: 0.85em;
    font-weight: 600;
  }


}

import React from "react";
import { cn } from '@/utils/cn'


interface SectionHeadingProps {
  children: React.ReactNode;
  className?: string;
}

export default function SectionHeading({
  children,
  className,
}: Readonly<SectionHeadingProps>) {
  return (
    <p
      className={cn(
        "text-3xl font-medium mb-4 ",
        className,
      )}
    >
      {children}
    </p>
  );
}

export { cn } from "cn"

export const currentYear = new Date().getFullYear().toString();
export function formatDate(date: string | Date): string {
  const dateObj = typeof date === "string" ? new Date(date) : date
  return new Intl.DateTimeFormat("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  }).format(dateObj)
}
